        ctx.globalAlpha = Math.max(0, flash.alpha) * flash.fillAlpha;
        ctx.fillStyle = `#${(flash.color & 0xffffff).toString(16).padStart(6, '0')}`;
        ctx.fillRect(0, 0, 630, 530);
